tutorpress_live_lessons_assert( array( 'candidates' => array( array( 'id' => 4, 'label' => 'Course' ) ), 'owner_id' => null, 'code' => 'legacy_owner_resolution_required' ) === $google_only && array( 'candidates' => array( array( 'id' => 9, 'label' => 'Post' ) ), 'owner_id' => null, 'code' => 'legacy_owner_resolution_required' ) === $google_post && array( 'candidates' => array( array( 'id' => 7, 'label' => 'Ada' ), array( 'id' => 8, 'label' => 'Bea' ) ), 'owner_id' => null, 'code' => 'legacy_owner_resolution_required' ) === $google_two, 'a google course author, a sole post author, or two acting users stays unresolved' );
